function validate([points]) {
  if (!Array.isArray(points) || points.length < 2 || points.length > 50) return 'points needs 2 to 50 entries.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(v => !Number.isInteger(v) || v < 0 || v > 50)) return 'Coordinates are integers from 0 to 50.';
    const key = p[0] * 100 + p[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  return null;
}

