function numberOfPairs(points) {
  points.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  let count = 0;

  for (let i = 0; i < points.length; i++) {
    const top = points[i][1];
    let highest = -Infinity;

    for (let j = i + 1; j < points.length; j++) {
      const y = points[j][1];
      if (y <= top && y > highest) {
        count++;
        highest = y;
      }
    }
  }
  return count;
}

