function numberOfPairs(points) {
  let total = 0;
  for (const a of points) {
    for (const b of points) {
      if (a === b || a[0] > b[0] || a[1] < b[1]) continue;
      let empty = true;
      for (const p of points) {
        if (p === a || p === b) continue;
        if (p[0] >= a[0] && p[0] <= b[0] && p[1] <= a[1] && p[1] >= b[1]) empty = false;
      }
      if (empty) total++;
    }
  }
  return total;
}

