function generate(rand, size) {
  const span = size === 'large' ? 51 : 2 + Math.floor(rand() * 6);
  const cells = span * span;
  const n = size === 'large' ? 50 : Math.min(cells, 2 + Math.floor(rand() * 9));
  const used = new Set();
  const points = [];
  while (points.length < n) {
    const x = Math.floor(rand() * span);
    const y = Math.floor(rand() * span);
    const key = x * 100 + y;
    if (used.has(key)) continue;
    used.add(key);
    points.push([x, y]);
  }
  return [points];
}
